    "index.js": "// Generated by the M5cet visual builder from flow.m5flow.json.\n// Edit the flow in Functions → Builder (changes here are replaced on the next save),\n// or use “Eject to code” there to keep working on this file by hand.\n\nconst __str = (v) => (v === undefined || v === null ? \"\" : typeof v === \"string\" ? v : typeof v === \"object\" && !(v instanceof Uint8Array) ? JSON.stringify(v, null, 2) : String(v));\nconst __get = (o, path) => String(path).split(\".\").filter(Boolean).reduce((a, k) => (a === undefined || a === null ? undefined : a[k]), o);\nconst __clean = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => v !== undefined && v !== null && v !== \"\"));\n\nexport async function execute(inputs = {}) {\n  // n1 · Form\n  const n_n1 = await m5.caller.send(m5.out.form({\"name\":\"tel-messenger\",\"title\":\"Messenger\",\"text\":\"Send a Facebook Messenger message\",\"submit\":\"Send\",\"labels\":\"top\",\"fields\":[{\"name\":\"to\",\"type\":\"text\",\"label\":\"Recipient (page-scoped id)\",\"required\":true,\"pattern\":\"^[0-9]{5,32}$\"},{\"name\":\"text\",\"type\":\"textarea\",\"label\":\"Text\",\"required\":true,\"rows\":3},{\"name\":\"tag\",\"type\":\"select\",\"label\":\"Outside 24 hours\",\"default\":\"\",\"options\":[{\"value\":\"\",\"label\":\"—\"},{\"value\":\"HUMAN_AGENT\",\"label\":\"HUMAN_AGENT\"}]}]}));\n  return null;\n}\n\nexport async function form(inputs = {}) {\n  // n2 · Entry point data\n  const n_n2 = inputs;\n  // n5 · Get field\n  const n_n5 = __get(n_n2.values, \"to\");\n  // n8 · Get field\n  const n_n8 = __get(n_n2.values, \"text\");\n  // n3 · WhatsApp / Viber / Messenger\n  const n_n3 = await m5.telephony.messenger({ ...__clean(n_n2.values || {}), ...__clean({ to: __str(n_n5), text: __str(n_n8), from: \"\", provider: \"\" }) });\n  // n13 · Get field\n  const n_n13 = __get(n_n2.values, \"to\");\n  // n15 · Get field\n  const n_n15 = __get(n_n3, \"status\");\n  // n11 · Template\n  const n_n11 = \"**Messenger to \" + __str(n_n13) + \"** — \" + __str(n_n15);\n  // n12 · Send Markdown\n  const n_n12 = await m5.caller.send(m5.out.markdown(__str(n_n11)));\n  return null;\n}\n\nexport async function error(inputs = {}) {\n  // n20 · Entry point data\n  const n_n20 = inputs;\n  // n21 · Get field\n  const n_n21 = __get(n_n20.error, \"message\");\n  // n22 · Flash\n  const n_n22 = await m5.caller.flash(__str(n_n21), \"error\");\n  return null;\n}\n\n"
